import csv, math
from collections import defaultdict

def mean(xs):
    return sum(xs)/len(xs) if xs else float('nan')

def pearson(x,y):
    mx=mean(x); my=mean(y)
    num=sum((a-mx)*(b-my) for a,b in zip(x,y))
    den=math.sqrt(sum((a-mx)**2 for a in x)*sum((b-my)**2 for b in y))
    return num/den if den else float('nan')

rows=[]
with open('benchmark/data.csv', newline='', encoding='utf-8') as f:
    r=csv.DictReader(f)
    for row in r:
        rows.append({
            'year': int(row['year']),
            'salary': float(row['salary']),
            'ai_risk_score': float(row['ai_risk_score']),
            'job_title': row['job_title'],
            'country': row['country'],
            'experience_level': row['experience_level'],
            'education_level': row['education_level'],
        })

by_year=defaultdict(lambda: ([],[]))
for r in rows:
    x,y=by_year[r['year']]
    x.append(r['salary']); y.append(r['ai_risk_score'])

for y in [2015,2020,2025,2030,2035]:
    x,yy=by_year[y]
    print(y, 'corr', round(pearson(x,yy),3))
PY"}

